import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-contact',
  standalone: true,
  imports: [CommonModule],
  template: `
    <section>
      <h1>Contact</h1>
      <p>Pour nous contacter : contact@tunjob.example</p>
    </section>
  `,
})
export class ContactComponent {}
